    "resultFieldProperties": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Propriétés des champs de la réponse" } },
    "id": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Clé primaire du champ. Permet de générer le nom de la colonne en base de données en ajoutant le prefix `field_`." } },
